"""Metadata processing for report-ledger."""

import json
import re

_DAY_PATTERN = re.compile(r'\d{4}-\d{2}-\d{2}')


def _parse_day(value):
    """Return a date for a strict YYYY-MM-DD string, or raise ValueError."""
    if not isinstance(value, str) or not _DAY_PATTERN.fullmatch(value):
        raise ValueError(f'day must be a YYYY-MM-DD string, got {value!r}')
    year, month, day = (int(part) for part in value.split('-'))
    if not 1 <= month <= 12 or not 1 <= day <= _days_in_month(year, month):
        raise ValueError(f'day is not a real calendar date: {value!r}')
    return year, month, day


def _days_in_month(year, month):
    if month in (1, 3, 5, 7, 8, 10, 12):
        return 31
    if month in (4, 6, 9, 11):
        return 30
    return 29 if _is_leap_year(year) else 28


def _is_leap_year(year):
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)


def _parse_row(row):
    """Validate one row and return its (amount_cents, day) parts."""
    if not isinstance(row, dict):
        raise ValueError(f'row must be an object, got {type(row).__name__}')

    tenant = row.get('tenant')
    if not isinstance(tenant, str) or not tenant:
        raise ValueError(f'tenant must be a nonempty string, got {tenant!r}')

    amount_cents = row.get('amount_cents')
    if isinstance(amount_cents, bool) or not isinstance(amount_cents, int):
        raise ValueError(f'amount_cents must be an integer, got {amount_cents!r}')

    return amount_cents, _parse_day(row.get('day'))


def summarize_rows(text: str):
    """Parse a JSON array of rows. Each row has a nonempty string tenant, an integer
    amount_cents (negative amounts are allowed; booleans are invalid), and a valid YYYY-
    MM-DD string day. Return row_count, total_cents, first_day, and last_day. Empty
    input gives zero totals and null dates. Ignore extra fields. Raise ValueError on
    malformed JSON or rows."""
    try:
        rows = json.loads(text)
    except ValueError as error:
        raise ValueError(f'malformed JSON: {error}') from error

    if not isinstance(rows, list):
        raise ValueError(f'top level must be an array, got {type(rows).__name__}')

    row_count = 0
    total_cents = 0
    first_day = None
    last_day = None
    for row in rows:
        amount_cents, day = _parse_row(row)
        row_count += 1
        total_cents += amount_cents
        if first_day is None or day < first_day:
            first_day = day
        if last_day is None or day > last_day:
            last_day = day

    return {
        'row_count': row_count,
        'total_cents': total_cents,
        'first_day': None if first_day is None else '%04d-%02d-%02d' % first_day,
        'last_day': None if last_day is None else '%04d-%02d-%02d' % last_day,
    }
